1	package chainledger
2	
3	import (
4		"reflect"
5		"testing"
6	)
7	
8	// This file pins the single relationship rule shared by graph reads
9	// (UnmarshalGraphFile/ParseSnapshot via lineageFromAdjacency) and batch
10	// applies (ApplyBatch via applyAdjacency): both materialize lineage through
11	// materializeLineage, so every dataset's direct upstreams correspond to those
12	// upstreams' direct downstreams, lists are sorted and duplicate-free, removed
13	// nodes leave no residual edges, and surviving node records keep exposing the
14	// updated relationships through the pointers callers already hold.
15	
16	// assertLineageConsistent checks the parent/child correspondence of every
17	// node: parents are sorted/deduped, every parent lists the node exactly once,
18	// and no child list references a missing dataset or repeats a name.
19	func assertLineageConsistent(t *testing.T, graph map[string]*Lineage) {
20		t.Helper()
21		for name, entry := range graph {
22			if entry == nil {
23				t.Errorf("graph[%q] is nil", name)
24				continue
25			}
26			if got := uniqueSorted(entry.Parents); !reflect.DeepEqual(got, entry.Parents) {
27				t.Errorf("%s.Parents = %v, want sorted and duplicate-free", name, entry.Parents)
28			}
29			if got := uniqueSorted(entry.Children); !reflect.DeepEqual(got, entry.Children) {
30				t.Errorf("%s.Children = %v, want sorted and duplicate-free", name, entry.Children)
31			}
32			for _, parent := range entry.Parents {
33				p, ok := graph[parent]
34				if !ok {
35					t.Errorf("%s lists upstream %q which is absent from the graph", name, parent)
36					continue
37				}
38				count := 0
39				for _, child := range p.Children {
40					if child == name {
41						count++
42					}
43				}
44				if count != 1 {
45					t.Errorf("upstream %q lists downstream %s %d times, want exactly once", parent, name, count)
46				}
47			}
48			for _, child := range entry.Children {
49				c, ok := graph[child]
50				if !ok {
51					t.Errorf("%s lists child %q which is absent from the graph", name, child)
52					continue
53				}
54				found := false
55				for _, parent := range c.Parents {
56					if parent == name {
57						found = true
58					}
59				}
60				if !found {
61					t.Errorf("%s lists child %q, but %s does not list it back as an upstream", name, child, child)
62				}
63			}
64		}
65	}
66	
67	// TestReadGraphMaterializesCorrespondingRelations covers the read side of the
68	// shared rule: after reading a legal graph, A is root, B depends on A, C
69	// depends on B, and D is a separate root — parent and child lists correspond.
70	func TestReadGraphMaterializesCorrespondingRelations(t *testing.T) {
71		data := []byte(`{
72	  "datasets": [
73	    {"name": "A", "upstreams": []},
74	    {"name": "B", "upstreams": ["A"]},
75	    {"name": "C", "upstreams": ["B"]},
76	    {"name": "D", "upstreams": []}
77	  ]
78	}`)
79		graph, err := UnmarshalGraphFile(data)
80		if err != nil {
81			t.Fatalf("UnmarshalGraphFile unexpected error: %v", err)
82		}
83		assertLineageConsistent(t, graph)
84		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"B"}) {
85			t.Errorf("A.Children = %v, want [B]", got)
86		}
87		if got := graph["B"].Parents; !reflect.DeepEqual(got, []string{"A"}) {
88			t.Errorf("B.Parents = %v, want [A]", got)
89		}
90		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
91			t.Errorf("B.Children = %v, want [C]", got)
92		}
93		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"B"}) {
94			t.Errorf("C.Parents = %v, want [B]", got)
95		}
96		if got := graph["D"].Children; len(got) != 0 {
97			t.Errorf("D.Children = %v, want empty", got)
98		}
99	}
100	
101	// TestApplyRepointUpstreamsFollowsSharedRule is the headline example: A is
102	// root, B depends on A, C depends on B, plus root D. After replacing B's
103	// upstreams with D, A no longer lists B, D lists B once, B still lists C, and
104	// C still depends on B.
105	func TestApplyRepointUpstreamsFollowsSharedRule(t *testing.T) {
106		graph := buildGraph(t, P("A"), P("D"), P("B", "A"), P("C", "B"))
107		heldB := graph["B"]
108		heldC := graph["C"]
109	
110		if _, err := ApplyBatch(graph, planOf(change("B", "D"))); err != nil {
111			t.Fatalf("ApplyBatch unexpected error: %v", err)
112		}
113		assertLineageConsistent(t, graph)
114	
115		if got := graph["A"].Children; len(got) != 0 {
116			t.Errorf("A.Children = %v, want empty (replaced edge dissolved)", got)
117		}
118		if got := graph["D"].Children; !reflect.DeepEqual(got, []string{"B"}) {
119			t.Errorf("D.Children = %v, want [B] exactly once", got)
120		}
121		if got := graph["B"].Parents; !reflect.DeepEqual(got, []string{"D"}) {
122			t.Errorf("B.Parents = %v, want [D]", got)
123		}
124		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
125			t.Errorf("B.Children = %v, want [C] (untouched downstream kept)", got)
126		}
127		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"B"}) {
128			t.Errorf("C.Parents = %v, want [B]", got)
129		}
130	
131		// Records the Go caller already held expose the updated relationships.
132		if heldB.Parents == nil || !reflect.DeepEqual(heldB.Parents, []string{"D"}) {
133			t.Errorf("held B record Parents = %v, want updated [D]", heldB.Parents)
134		}
135		if !reflect.DeepEqual(heldB.Children, []string{"C"}) {
136			t.Errorf("held B record Children = %v, want retained [C]", heldB.Children)
137		}
138		if !reflect.DeepEqual(heldC.Parents, []string{"B"}) {
139			t.Errorf("held C record Parents = %v, want unchanged [B]", heldC.Parents)
140		}
141	}
142	
143	// TestApplyMakeRootKeepsDownstreamFollowsSharedRule verifies that turning B
144	// into a root through a batch does not let the unified rebuild discard C: A
145	// drops B, B lists no parents but still lists C.
146	func TestApplyMakeRootKeepsDownstreamFollowsSharedRule(t *testing.T) {
147		graph := buildGraph(t, P("A"), P("D"), P("B", "A"), P("C", "B"))
148	
149		if _, err := ApplyBatch(graph, planOf(change("B"))); err != nil {
150			t.Fatalf("ApplyBatch unexpected error: %v", err)
151		}
152		assertLineageConsistent(t, graph)
153	
154		if got := graph["B"].Parents; len(got) != 0 {
155			t.Errorf("B.Parents = %v, want empty (root)", got)
156		}
157		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
158			t.Errorf("B.Children = %v, want [C] (downstream survives becoming root)", got)
159		}
160		if got := graph["A"].Children; len(got) != 0 {
161			t.Errorf("A.Children = %v, want empty", got)
162		}
163		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"B"}) {
164			t.Errorf("C.Parents = %v, want [B]", got)
165		}
166		if got := Roots(graph); !reflect.DeepEqual(got, []string{"A", "B", "D"}) {
167			t.Errorf("Roots = %v, want [A B D]", got)
168		}
169	}
170	
171	// TestApplyRemovalLeavesNoResidualEdges verifies a deleted dataset disappears
172	// completely: no node retains it and no retained parent keeps listing it.
173	func TestApplyRemovalLeavesNoResidualEdges(t *testing.T) {
174		graph := buildGraph(t, P("A"), P("B", "A"), P("C", "B"), P("D"))
175		heldC := graph["C"]
176	
177		plan := Plan{
178			Changes:  []PlanChange{change("B", "D")},
179			Removals: []string{"A"},
180		}
181		if _, err := ApplyBatch(graph, plan); err != nil {
182			t.Fatalf("ApplyBatch unexpected error: %v", err)
183		}
184		assertLineageConsistent(t, graph)
185	
186		if _, ok := graph["A"]; ok {
187			t.Errorf("removed dataset A still present in the graph")
188		}
189		for name, entry := range graph {
190			for _, parent := range entry.Parents {
191				if parent == "A" {
192					t.Errorf("retained dataset %s still references removed A", name)
193				}
194			}
195			for _, child := range entry.Children {
196				if child == "A" {
197					t.Errorf("retained dataset %s still lists removed A as a child", name)
198				}
199			}
200		}
201		if got := graph["B"].Parents; !reflect.DeepEqual(got, []string{"D"}) {
202			t.Errorf("B.Parents = %v, want [D]", got)
203		}
204		// The held record for a surviving dataset reflects the rebuild.
205		if !reflect.DeepEqual(heldC.Parents, []string{"B"}) {
206			t.Errorf("held C record Parents = %v, want [B]", heldC.Parents)
207		}
208	}
209	
210	// TestApplyDeleteAllThenAddKeepsGraphLegal exercises the empty-graph boundary
211	// through the same materialization: deleting every dataset leaves a usable
212	// empty graph, and a later registration through a batch works normally.
213	func TestApplyDeleteAllThenAddKeepsGraphLegal(t *testing.T) {
214		graph := buildGraph(t, P("A"), P("B", "A"))
215	
216		if _, err := ApplyBatch(graph, Plan{Removals: []string{"A", "B"}}); err != nil {
217			t.Fatalf("ApplyBatch delete-all unexpected error: %v", err)
218		}
219		if len(graph) != 0 {
220			t.Fatalf("graph = %v, want empty", graph)
221		}
222		assertLineageConsistent(t, graph)
223	
