236		t.Run("single registration replacing edges judged by final shape", func(t *testing.T) {
237			// A<-B. Re-register B depending on a fresh child-less dataset is
238			// fine; the key case: B stays on A but also gains a parent that
239			// only reaches B via an edge removed in THIS registration.
240			// A<-B, A<-D, change D to depend on nothing, B drops nothing.
241			graph := map[string]*Lineage{}
242			mustRegister(t, graph, "A")
243			mustRegister(t, graph, "B", "A")
244			mustRegister(t, graph, "D", "A")
245			// D used to reach A directly; make D a root while keeping A->? ...
