262		}
263		if _, exists := graph["B"]; exists {
264			t.Fatal("dataset B node was created despite invalid later upstream")
265		}
266		if got := graph["A"].Children; len(got) != 0 {
267			t.Fatalf("A.Children = %v, want empty (no partial edges)", got)
268		}
269	
