func TestRegisterSharedStorageKeepsDownstreamOfRepointedDataset(t *testing.T) {
	// C itself has a downstream; shared roots, and C.Children rides along on
	// storage it happens to share via a spare-capacity window.
	rootShared := []string{"C", "D"}
	kids := make([]string, 2, 4)
